INSERT INTO pm_book (slug, title, subtitle, author, year, cover_path) VALUES ('ppd', 'PPD Class', 'Pengembangan Produk Digital', 'UI Course', 2025, '') ON CONFLICT (slug) DO NOTHING;
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'cdh'), 'Experience Map', 'Discovery', 'End-to-end customer journey used to surface pain points', '["Set scope based on your desired outcome (narrow for optimization, broad for exploration)","Each trio member maps the customer journey individually (avoid groupthink)","Merge all maps into one shared version using nodes (moments) and links (arrows)","Include unhappy paths: where customers get frustrated, loop back, or abandon","Update weekly as you learn more from interviews"]'::jsonb, '/figures/cdh/cdh_p55.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'cdh'), 'Story-Based Interview', 'Discovery', 'Elicit specific past stories using temporal prompts, not direct questions', '["Write research questions (what the team wants to learn)","Convert to interview questions that elicit specific past stories (\"Tell me about the last time you...\")","Use temporal prompts: \"What happened first?\" \"What happened next?\"","Never ask about the future or hypotheticals","Whole trio participates; each role hears different things"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'cdh'), 'Interview Snapshot', 'Discovery', 'One-page synthesis: quote, insight, opportunity per interview', '["Take a photo of the interviewee (with permission) to aid memory","Pick one memorable quote that captures their experience","Note quick facts for context (role, usage patterns)","List insights: what surprised you or confirmed assumptions","Frame opportunities as needs (\"I don''t want to...\") not features (\"I want a button that...\")"]'::jsonb, '/figures/cdh/cdh_p69.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'cdh'), 'Opportunity Solution Tree (OST)', 'Discovery', 'Visual tree linking outcome to opportunities to solutions to experiments', '["Place your desired outcome at the top","Branch into opportunities (needs, pain points, desires) from interviews","Use parent-child relationships (subsets) and sibling relationships (distinct alternatives)","Add solutions as children of each opportunity (aim for 3+ per opportunity)","Add assumption tests as children of each solution"]'::jsonb, '/figures/cdh/cdh_p26.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'cdh'), 'Opportunity Assessment', 'Strategy', 'Evaluate siblings by four lenses: sizing, market, company, customer factors', '["List sibling opportunities at the same level of the tree","Score each on four lenses: Opportunity sizing (how many customers, how often?), Market factors (table stakes or differentiator?), Company factors (aligned with mission and strategy?), Customer factors (how important to them, how satisfied with current solutions?)","Pick one leaf-node opportunity to focus on (limit WIP)","Treat as a two-way door decision: move fast, reverse if wrong"]'::jsonb, '/figures/cdh/cdh_p99.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'cdh'), 'Story Map (Solution-Level)', 'Validation', 'Steps a user takes to get value from a solution, surfacing assumptions at each step', '["Pick one solution idea from the OST","Map the specific steps a user takes to get value from it","At each step, ask: what must be true for this to work?","Categorize surfaced assumptions: desirability, viability, feasibility, usability, ethical","Feed the riskiest assumptions into the Assumption Map"]'::jsonb, '/figures/cdh/cdh_p124.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'cdh'), 'Pre-Mortem', 'Validation', 'Team imagines the product failed 6 months out and lists reasons why', '["Imagine it is 6 months from now and the product has failed","Each trio member writes down reasons for the failure individually","Share and cluster the reasons","Identify which are desirability, viability, feasibility, usability, or ethical risks","Add the most critical ones to the Assumption Map"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'cdh'), 'Assumption Map', 'Validation', '2x2 matrix plotting assumptions by importance vs. evidence', '["Draw a 2x2 grid: X-axis (strong evidence to weak evidence), Y-axis (less important to more important)","List all assumptions from Story Maps, Pre-Mortems, and OST lines","Place each assumption on the grid","The top-right quadrant (high importance, weak evidence) = \"leap of faith\" assumptions","Test leap-of-faith assumptions first"]'::jsonb, '/figures/cdh/cdh_p131.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'cdh'), 'Assumption Test', 'Validation', 'Simulate a moment, evaluate behavior, define success criteria before running', '["Pick the highest-risk assumption from the Assumption Map","Design a simulation of the specific moment the user would encounter it","Define success criteria with specific numbers before running (\"3 out of 5 people will...\")","Run the test (one-question survey, unmoderated test, prototype, data mining)","Update the Assumption Map: move the assumption left if evidence gained"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'cdh'), 'Continuous Interviewing Cadence', 'Process', 'Weekly interview habit with automated recruiting for the Product Trio', '["Set a target: at least one customer interview per week","Automate recruiting (in-app triggers, scheduling software, standing calendar slots)","Whole trio attends each interview","Synthesize after every interview (Interview Snapshot), not in batches","Review and update the OST weekly based on new learnings"]'::jsonb, '/figures/cdh/cdh_p17.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'inspired'), 'Business Context', 'Strategy', 'Vision + strategy + objectives replacing traditional roadmaps', '["Identify the product vision (2-5 year future state) and the product strategy (sequence of milestones to reach it)","Define specific business objectives for each product team, measured by outcomes rather than feature completion","Map each team''s work to a clear customer problem and target market segment","Replace the traditional feature roadmap with a shared understanding of vision, strategy, and team-level objectives","Communicate context continuously so empowered teams can make good autonomous decisions"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'inspired'), 'High-Integrity Commitment', 'Strategy', 'Structured promise to stakeholders with evidence backing', '["Resist committing to delivery dates at the roadmap stage when uncertainty is highest","Request time for product discovery first to validate value, usability, feasibility, and business viability","Use prototypes and tests to reduce the four risks before making any promise","Once the solution is validated, commit to a specific delivery date and expected business result","Score committed objectives at 1.0 (binary pass/fail) rather than the 0.7 aspirational OKR scale"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'inspired'), 'Product Vision', 'Strategy', '3-5 year north star for the product', '["Start with \"why\" by articulating the purpose behind the product and the problem worth solving","Think big: frame a 2-5 year ambitious future state that inspires the team and serves as a recruiting tool","Fall in love with the problem, not any particular solution","Be stubborn on the vision but flexible on the details; allow discovery to pivot the \"how\"","Evangelize the vision near-constantly across the organization to prevent confusion and maintain alignment"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'inspired'), 'Product Strategy', 'Strategy', 'How to achieve the vision: focus areas, sequence, leverage', '["Focus on one target market or persona at a time rather than trying to please everyone","Sequence product releases as deliberate milestones that build toward the vision","Align product goals with the company''s monetization model and business strategy","Obsess over customers rather than competitors; customers leave when you stop serving them well","Review and adjust the strategy as you gain evidence from each market segment"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'inspired'), 'Product Principles', 'Strategy', 'Decision-making guardrails for the team', '["Identify decisions where two valid options create recurring tension (e.g., buyer vs. seller priority)","State the principle as a clear, opinionated stance the team commits to (not a vague platitude)","Use the principle to resolve conflicts quickly without re-debating the same trade-off each time","Communicate principles alongside the vision so teams understand the \"nature\" of the product you want to build","Revisit principles when the market or business model changes significantly"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'inspired'), 'OKR Technique', 'Measurement', 'Objectives + measurable Key Results per quarter', '["Set qualitative, inspirational objectives at the company level, then cascade to product teams","Define 1-3 quantitative key results per objective that measure business outcomes, not feature delivery","Score on a 0-to-1.0 scale where 0.7 indicates success on aspirational goals","Assign OKRs to cross-functional product teams (not functional silos like Design or Engineering separately)","Have leadership reconcile proposed key results across teams to close gaps and resolve conflicts"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'inspired'), 'Opportunity Assessment (INSPIRED)', 'Discovery', '4 questions: objective, key results, customer problem, target market', '["State the business objective this effort addresses (which company or team OKR)","Define the key results that will indicate success","Describe the specific customer problem you are solving","Identify the target market or customer segment","Use these four answers to align the team and filter out efforts that lack clear purpose"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'inspired'), 'Customer Letter', 'Discovery', 'Amazon-style letter from a happy customer to the CEO', '["Imagine the product has launched successfully and a delighted customer writes to the CEO","Write the letter from the customer''s perspective describing how the product improved their life","Focus on the emotional and practical benefits the customer experienced, not technical features","Use the letter to pressure-test whether the team truly understands the value proposition","Share the letter with the team as a north-star framing artifact before starting discovery"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'inspired'), 'Startup Canvas', 'Discovery', 'Lightweight alternative to business plans for new product lines', '["Use as a lightweight alternative to a full business plan when exploring a new product line or venture","Identify the biggest risks: value proposition, customer segments, channels, and revenue model","Keep each section concise; the canvas is a thinking tool, not a comprehensive document","Prioritize the riskiest assumptions (typically value proposition and distribution) for early testing","Update the canvas iteratively as discovery experiments provide evidence"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'inspired'), 'Story Map', 'Discovery', '2D map: horizontal user activities, vertical detailed tasks', '["Lay out the major user activities horizontally across the top to show the end-to-end journey","Under each activity, add detailed user tasks vertically, ordered by priority or sequence","Draw a horizontal line to define the minimum viable slice that delivers value","Use the map to provide holistic context for the product backlog rather than a flat list of stories","Walk the entire team through the map so everyone shares the same mental model of the product"]'::jsonb, '/figures/usm/usm_p19.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'inspired'), 'Reference Customers', 'Discovery', 'Six real users paying real money and willing to vouch for the product', '["Set a target of six reference customers in a single target market segment","Recruit real users who are paying real money (not friends, family, or free-tier users)","Work closely with each reference customer through discovery and iteration until they are genuinely successful","Ask reference customers to publicly vouch for the product (case studies, references, peer recommendations)","Only declare product/market fit and expand to adjacent markets once you have earned your reference customers"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'inspired'), 'Prototypes', 'Validation', 'Feasibility, user, live-data, and hybrid (Wizard of Oz) prototypes', '["Choose the prototype fidelity based on the risk: feasibility prototypes for technical risk, user prototypes for usability and value risk","Build feasibility prototypes as minimal code spikes written by engineers to test performance, scalability, or third-party integration","Create user prototypes ranging from low-fidelity wireframes (for structure) to high-fidelity clickable simulations (for realistic testing)","Use live-data prototypes when you need real data and traffic to validate an algorithm or recommendation engine","Consider Wizard-of-Oz prototypes where a human performs the back-end task behind a realistic front end to simulate automation before building it"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'outcomes'), 'Program Logic Model', 'Strategy', 'Chain: Activities -> Outputs -> Outcomes -> Impact', '["Define the resources available: people, money, and materials","List the activities (work performed) that consume those resources","Identify the outputs - the tangible products or deliverables created","Specify the outcomes - the measurable changes in human behavior those outputs produce","Connect outcomes to the ultimate impact (e.g., higher revenue, better standard of living)"]'::jsonb, '/figures/ooo/ooo_p10.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'outcomes'), 'Magic Questions', 'Discovery', 'Three questions to move from features to behavioral outcomes', '["Ask: \"What are the user and customer behaviors that drive business results?\" to identify target outcomes","Ask: \"How can we get people to do more of those behaviors?\" to generate possible features, policy changes, or promotions","Ask: \"How do we know that we''re right?\" to define tests and metrics for measuring progress","Write each answer on a shared whiteboard so the team can see the chain from behavior to result","Revisit these questions at the start of every planning cycle to keep the team outcome-focused"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'outcomes'), 'Leading Indicators', 'Measurement', 'Observable behaviors that predict future business results', '["List your lagging indicators (metrics that report the past, e.g., annual return rate)","For each lagging indicator, brainstorm observable behaviors that predict its movement","Select the behaviors with the strongest predictive link to future success (e.g., social sharing, newsletter opens)","Define how you will measure each leading indicator at a regular cadence","Target these leading indicators as team outcomes instead of chasing lagging metrics"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'outcomes'), 'Outcome-Based Key Results', 'Measurement', 'OKRs where key results are measurable customer behaviors, not feature launches', '["Write an Objective that describes the desired qualitative change","Draft Key Results as measurable customer or user behaviors, not feature launches","Validate each Key Result by checking: \"If this behavior increases, does it plausibly drive the Objective?\"","Set specific numeric targets with time bounds (e.g., \"1,000 new registrations in the first week\")","Review weekly; if a Key Result is not moving, treat it as a signal to experiment with different solutions"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'outcomes'), 'Customer Journey Map (Boosters/Blockers)', 'Discovery', 'Journey annotated with what helps and hurts target behavior', '["Draw swim lanes for each actor (buyer, seller, internal team) across the service timeline","Map the actual behaviors at each step of the journey from first contact to goal completion","Mark Boosters (+): behaviors that predict satisfaction and drive business results","Mark Blockers (-): behaviors that predict dissatisfaction or abandonment","Convert the most impactful Boosters and Blockers into outcome hypotheses for the roadmap"]'::jsonb, '/figures/ooo/ooo_p31.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'outcomes'), 'Outcome-Based Roadmap', 'Strategy', 'Hypotheses about which behaviors to change, not features to ship', '["Replace the feature-list roadmap with themes framed as behavior changes to deliver","For each theme, write a hypothesis: \"We believe that increasing [Behavior A] will lead to [Business Impact B]\"","Prioritize themes by their expected impact on leading indicators","Plan experiments (MVPs) to test each hypothesis before committing full resources","Update the roadmap as experiments confirm or disprove hypotheses - treat it as a living document"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'sprint'), 'Sprint Challenge', 'Strategy', 'High-stakes problem worth a week of intense focus', '["Evaluate whether your problem meets the sprint criteria: high stakes, not enough time, or just plain stuck","Identify the big question the sprint must answer by the end of the week","Choose to solve the surface first - focus on the customer-facing interface, not the back-end","Assemble the right team (seven or fewer) including a Decider and a Facilitator","Block five full days (Mon-Thu 10 a.m.-5 p.m., Fri 9 a.m.-5 p.m.) with no-device rules in the sprint room"]'::jsonb, '/figures/sprint/sprint_p3.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'sprint'), 'Long-term Goal + Sprint Questions', 'Strategy', 'North star + "can we..." risk questions to answer', '["Write an optimistic long-term goal answering where you want to be in six months to five years","Post the goal at the top of the whiteboard as the team''s North Star","Imagine the project has failed - each team member lists reasons for the failure","Rephrase each fear as a testable question (e.g., \"Will customers trust our expertise?\")","Record all sprint questions on the whiteboard below the goal; these guide the week''s decisions"]'::jsonb, '/figures/sprint/sprint_p94.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'sprint'), 'Map', 'Discovery', 'Simple customer journey: actors on left, ending on right, 5-15 steps', '["List the key actors (customers, users) on the left side of the whiteboard","Place the ending goal (e.g., \"purchase complete\") on the right side","Draw 5-15 steps showing how customers move from start to finish using words, arrows, and boxes","Keep the map simple and customer-centric - avoid technical implementation details","Update the map during expert interviews as new steps or gaps are discovered"]'::jsonb, '/figures/sprint/sprint_p91.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'sprint'), 'HMW Notes', 'Discovery', '"How Might We" opportunity notes from expert interviews', '["During expert interviews, reframe every problem heard as a \"How might we...?\" note on a sticky","Write one idea per sticky note so each can be moved independently","After interviews, organize all HMW notes into themed columns on a wall","Dot-vote: each team member gets two dots, the Decider gets four, to mark the most promising questions","Move the highest-voted HMW notes onto the map near the relevant steps; the Decider picks the target customer and target event"]'::jsonb, '/figures/sprint/sprint_p80.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'sprint'), 'Lightning Demos', 'Discovery', '3-minute tours of solutions from other products and domains', '["Each team member lists products or services that solve a similar problem - including from completely different domains","Give three-minute tours of each solution, highlighting what makes it effective","The Facilitator captures each \"big idea\" on the whiteboard with a quick sketch and a headline","Build a \"greatest hits\" reference wall of inspiring solutions for the team to use during sketching","Decide whether to \"swarm\" one target or \"divide\" the map among team members before sketching begins"]'::jsonb, '/figures/sprint/sprint_p103.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'sprint'), 'Solution Sketch (Four-Step)', 'Discovery', 'Individual detailed sketch: notes, ideas, crazy 8s, solution sketch', '["Notes (20 min): walk around the room reviewing the goal, map, HMW votes, and Lightning Demo ideas","Ideas (20 min): jot down rough concepts and doodles privately - these are not shared","Crazy 8s (8 min): fold a sheet into eight panels and sketch eight variations of your strongest idea, one per minute","Solution Sketch (30+ min): create a detailed, self-explanatory three-panel storyboard with real words and a catchy title","Submit anonymously - no names on sketches - so they are judged on content alone on Wednesday"]'::jsonb, '/figures/sprint/sprint_p115.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'sprint'), 'Storyboard', 'Delivery', '15-frame grid blueprint for the prototype', '["Draw a grid of approximately 15 frames on a whiteboard","Choose the opening scene: how the customer first encounters the product (web search, news article, store shelf)","Fill frames by stringing together the winning sketches from the Sticky Decision vote","Plug gaps with \"maybe-later\" ideas or existing product screens - do not brainstorm new solutions","Ensure the entire storyboard flow can be tested within a 15-minute window during Friday interviews"]'::jsonb, '/figures/sprint/sprint_p159.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'sprint'), 'Prototype', 'Validation', 'Realistic facade built in one day using Keynote, slides, or props', '["Pick rougher, faster tools (Keynote, PowerPoint, website builders) instead of production tools","Divide the storyboard into parts and assign roles: Makers, Stitcher, Writer, Asset Collector, Interviewer","Makers build individual components; the Stitcher combines them into one consistent experience","The Writer crafts realistic text (no lorem ipsum) while the Asset Collector gathers photos, icons, and sample content","Run a trial by 3 p.m. - the full team walks through the prototype to catch bugs and confirm it answers the sprint questions"]'::jsonb, '/figures/sprint/sprint_p173.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'sprint'), 'Five-Act Interview', 'Validation', 'Welcome, context, introduce prototype, tasks, debrief', '["Friendly Welcome: greet the customer warmly, clarify you are testing the product not the person","Context Questions: ask open-ended questions about the customer''s life and habits to build rapport","Introduce the Prototype: show the prototype, ask them to think aloud, and distance yourself (\"I didn''t design this\")","Tasks and Nudges: give realistic, open-ended tasks and observe how they navigate without offering help","Quick Debrief: ask overarching experience questions and use \"magic wishes\" to surface desired improvements"]'::jsonb, '/figures/sprint/sprint_p206.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'sprint'), 'The Grid', 'Measurement', 'Whiteboard: 5 columns (customers) x rows (prototype parts), color-coded notes', '["Draw a whiteboard grid with five columns (one per customer) and rows for each prototype section or sprint question","While watching each interview on the live feed, write observations on color-coded sticky notes: green (positive), red (negative), black (neutral)","Place each sticky note in the matching cell on the grid","After all five interviews, review the grid together to spot patterns appearing with three or more customers","Compare patterns against Monday''s sprint questions; the Decider makes the final call on next steps"]'::jsonb, '/figures/sprint/sprint_p224.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'momtest'), 'The Three Rules', 'Discovery', 'Talk about their life, ask about specifics in the past, talk less and listen more', '["Reframe every question to focus on the customer''s life, not your idea - ask about their workflow, frustrations, and goals","Anchor all responses to specifics in the past - replace hypotheticals with \"Tell me about the last time that happened\"","When you catch yourself talking or pitching, stop, apologize, and redirect to listening","After each conversation, check: did you learn concrete facts, or just collect opinions and compliments?"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'momtest'), 'Currencies of Conversation', 'Validation', 'Evaluate meetings by commitments of time, reputation, or money', '["Identify the three currencies a customer can give: time, reputation risk, or money","At the end of every meeting, push for a concrete commitment in at least one currency (e.g., a follow-up meeting with defined goals, an intro to a decision-maker, or a pre-order)","Classify the outcome: advancement (moved to next funnel stage) or failure (compliment or stalling tactic)","Watch for zombie leads who keep meeting but never commit - cut them loose and refocus on leads who give real currency","Use rejection (\"no\") as a valid, clarifying data point rather than treating it as a loss"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'momtest'), 'Who-Where Pairs', 'Discovery', 'Specific customer slice + where to find them', '["Start with a broad customer segment and slice it by asking: within this group, who wants this most and why?","Keep slicing until you find a sub-group with consistent problems, goals, and motivations","For each sub-group, identify where you can physically find them (conferences, communities, departments)","Evaluate each pair on three criteria: profitable (can pay), easy to reach (accessible), and rewarding (worth building for)","If feedback remains inconsistent after 10 conversations, the segment is still too broad - slice again"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'momtest'), 'Five-Element Framing', 'Process', 'Vision, Framing, Weakness, Pedestal, Ask (Very Few Wizards Properly Ask)', '["Open with your Vision: a half-sentence on the big problem you are trying to solve (not your product)","State your Framing: explain your current stage and clarify you have nothing to sell yet","Show a Weakness: name a specific challenge you are struggling to understand","Place them on a Pedestal: explain why they, specifically, are uniquely qualified to help","Make the Ask: request a specific, small amount of their time (use the mnemonic Very Few Wizards Properly Ask)"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'momtest'), 'The Golden Rule of Prep', 'Process', 'Identify the 3 biggest questions before any batch of interviews', '["Before any batch of interviews, write down the three most important (and scariest) things you need to learn","Spend up to one hour updating your best guesses about what the customer cares about - the meeting validates or invalidates these","Do desk research first: if a question can be answered via a search engine, do not waste conversation time on it","Ask the pre-mortem question: \"If this company fails, why will it have happened?\" to surface hidden risks","Replace any question you have reliable data on with the next murkiest unknown on your list"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'momtest'), 'Shorthand Symbols', 'Process', 'Icons for pain, goal, obstacle, feature request, money, follow-up', '["During live note-taking, use emotion symbols: :) for excited, :( for angry, :| for embarrassed","Mark life and context signals: lightning bolt for pain/problem, goal icon for job-to-be-done, square for obstacle, curved arrow for workaround, caret for background","Tag specifics: checkbox for feature request or purchasing criteria, dollar sign for money/budget, person icon for a specific person or company mentioned, star for follow-up task","Capture exact verbatim quotes - these are powerful for marketing copy, fundraising decks, and resolving internal debates","Store notes in a permanent, retrievable, sortable medium (index cards for physical sorting, or a shared spreadsheet/doc for digital teams)"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'momtest'), 'Note Review', 'Discovery', 'Team reviews notes together to update beliefs and refine questions', '["After every conversation, review notes together as a team to update collective beliefs","Conduct a meta-level review: which questions worked, which signals were missed, and how to improve the interview craft","Use the two-person rule: one leads the talk, one takes detailed notes, then both debrief to catch biases","Update the three big questions based on what was learned - retire answered ones, promote new unknowns","Check for warning signs: if you are talking more than listening, ideas remain unchanged despite new data, or you avoided scary questions, the process needs correction"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'usm'), 'Story Map (USM)', 'Delivery', 'Backbone (narrative flow) + body (details), left-to-right, top-to-bottom', '["Frame the problem first: identify who the product is for and why it is being built before writing any cards","Map the backbone left to right in narrative flow - write each high-level user activity on a card using the Think-Write-Explain-Place habit","Decompose each activity top to bottom into user tasks (verb phrases), exploring alternatives and exceptions by playing \"What About\"","Keep it mile wide, inch deep: cover the full breadth of the user journey before diving into details on any single activity","Use the map to find holes - missing steps, unclear handoffs, or gaps that a flat backlog would hide"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'usm'), 'MVPe', 'Delivery', 'Smallest thing to build to learn if a hypothesis is correct', '["Start with the story map backbone and identify the specific hypothesis you need to test (not a product to ship)","Slice the smallest possible set of tasks from the map that would let you run an experiment and learn","Build only what is needed to observe real user behavior - it does not need to be \"viable\" for the general market","Measure success through behavioral metrics (actual usage) rather than verbal feedback or politeness","Update the map backbone and details based on what you learned, then design the next experiment"]'::jsonb, '/figures/usm/usm_p89.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'usm'), 'Functional Walking Skeleton', 'Delivery', 'Thinnest end-to-end slice tackling highest technical risks first', '["Identify the essential functional path through the story map - the minimum end-to-end flow a user must complete","Slice this as the Opening Game: build just enough to see the product working from start to finish","Address the highest technical risks first within this skeleton (infrastructure, integration points, unknowns)","In the Midgame, fill in tough business rules and begin testing for performance, scalability, and usability","In the Endgame, refine based on real data at scale and apply feedback gathered from earlier slices"]'::jsonb, '/figures/usm/usm_p56.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'usm'), 'Release Slicing', 'Delivery', 'Horizontal cuts: Opening, Midgame, Endgame with outcome goals', '["Draw horizontal lines across the story map to group tasks into distinct releases, each targeting a specific outcome","For each slice, define the desired outcome (not just the features) - ask what user or business behavior should change","Apply the minimization principle: everything above the line is necessary for the release to be viable, everything below is deferred","Categorize features within each slice as table stakes, differentiators, spoilers, or cost reducers to sharpen focus","Treat each release as a learning opportunity - plan to adjust later slices based on what earlier releases reveal"]'::jsonb, '/figures/usm/usm_p98.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'usm'), 'The 3 Cs', 'Delivery', 'Card, Conversation, Confirmation for each user story', '["Write the story on a Card - keep it short (a title and brief description) as a token to identify the conversation, not replace it","Hold the Conversation with the people who have the problem and those who can solve it - use sketches, UI wireframes, and whiteboard drawings to externalize thinking","Define Confirmation criteria (acceptance tests) that specify when the story is truly done","Treat the card as a library catalog entry: it points to the real knowledge, which lives in the team''s shared understanding","After building, inspect results across three quality dimensions: user experience, functional correctness, and code maintainability"]'::jsonb, '/figures/usm/usm_p135.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'usm'), 'Three Amigos', 'Process', 'Developer + Tester + Product discovery member agree on acceptance criteria', '["Assemble three roles for the story workshop: a Product Owner or BA (value lens), a Developer (feasibility lens), and a Tester (\"what about\" lens)","Walk through the story card together, discussing who the user is, what they need, and why it matters","Have the Tester challenge the story with failure modes and edge cases to surface hidden acceptance criteria","Agree on specific confirmation criteria that all three roles understand and accept before development begins","Use the fishbowl technique for larger groups: the core trio works in the center while observers swap in only when they have something to add"]'::jsonb, '/figures/usm/usm_p203.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'usm'), 'Discovery Triad', 'Discovery', 'Product Owner + UX Designer + Senior Engineer ensure valuable, usable, feasible', '["Form a small cross-functional team of 2-4 people: a Product Owner, a UX Designer, and a Senior Engineer","Explore opportunities together by discussing who the users are, what problems they face, and what solutions might work","Evaluate every proposed solution against three lenses: Valuable (business/customer), Usable (user experience), and Feasible (technical implementation)","Use prototypes, design comics, and story maps to envision the solution visually before committing to code","Output a minimum viable solution definition - cut more ideas than you keep to maximize outcomes while minimizing output"]'::jsonb, '/figures/usm/usm_p200.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'usm'), 'Opportunity Canvas', 'Discovery', 'One-page canvas: problem, users, solutions, metrics, budget', '["Write the problem or idea name at the top, then describe the target users and customers in the first section","Document the specific problems or needs these users have and how they currently cope (existing solutions or workarounds)","State the proposed solution concept and the user value it delivers - what changes for the user?","Define the business metrics that will indicate success and identify any budget, timeline, or technical constraints","Use the completed canvas as a go/no-go filter: trash opportunities that do not offer clear hope for the desired outcomes"]'::jsonb, '/figures/usm/usm_p212_0.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'usm'), 'Personas', 'Discovery', 'Sketches of target users based on facts and assumptions', '["Identify the distinct user types who will interact with the product - give each a name, a sketch or photo, and a brief demographic context","Base persona details on facts from real user research and interviews, flagging any attributes that are assumptions","For each persona, list their primary goals, key frustrations, and the context in which they use the product","In B2B settings, create Orgzonas alongside individual personas to capture organizational goals and purchasing dynamics","Use personas during story mapping by color-coding cards per persona and walking through the map in character during rehearsal remapping"]'::jsonb, '/figures/usm/usm_p226.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'usm'), 'The Report Card', 'Measurement', 'Grade major user activities A-F across the story map backbone', '["Near the release date, list the major user activities from the story map backbone as rows in a grading sheet","Grade each activity from A to F based on its current quality and completeness","Identify any activity with a D or F grade as a critical focus area for the remaining development time","Discuss grades with the team to ensure the assessment reflects user experience quality, functional correctness, and not just feature count","Use the report card to make a ship-or-delay decision: all critical activities must reach a passing grade before release"]'::jsonb, '/figures/usm/usm_p299.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'ps101'), 'Logic Tree', 'Analysis', 'Break a large problem into smaller categories, no overlap, no one left out', '["State the broad problem or question on the left side of the tree","Break it into major categories ensuring no overlaps and no gaps (the \"no one gets left out\" rule)","Subdivide each category into finer sub-branches moving left to right","Verify each level: confirm branches are mutually exclusive and collectively exhaustive","Use the completed tree to pinpoint which branch deserves investigation or action"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'ps101'), 'Yes/No Tree', 'Analysis', 'Binary buckets to pinpoint where a process breaks down', '["Define the population or set you want to analyze (e.g., all potential customers)","Pose a binary yes/no question that splits the set into two buckets","For each bucket, pose the next binary question to split further","Continue until each terminal bucket represents a distinct, actionable segment","Identify the bucket with the biggest drop-off or problem and focus resources there"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'ps101'), 'Problem-Solving Design Plan', 'Analysis', 'Clarify questions, state hypotheses, list rationale and data needed', '["Write down the specific question you need to answer","State your hypothesis (your best current guess) and the rationale behind it","List the analyses or information sources needed to confirm or refute the hypothesis","Collect and analyze the data, then compare actual results against your hypothesis","Revise the hypothesis if disproven and repeat until the root cause is identified"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'ps101'), 'Hypothesis Pyramid', 'Analysis', 'Conclusion at top, supporting rationales at bottom', '["Place the main conclusion or recommendation at the top of the pyramid","Below it, list 2-4 supporting rationales or sub-conclusions","For each rationale, add the evidence or data points that back it up","Decide the structure: grouping (independent supports) or argument (sequential chain)","Test robustness: remove one support block and check whether the conclusion still holds"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'ps101'), 'Gap Analysis', 'Strategy', 'Goal vs. current state, then logic tree to close the gap', '["Set a clear, specific goal with measurable conditions and a deadline","Determine your current state using concrete numbers","Calculate the gap between the goal and the current state","Use a logic tree to brainstorm ways to close the gap (e.g., increase income vs. reduce spending)","Select the most feasible options and build a concrete action plan with milestones"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'ps101'), 'Impact vs. Ease Matrix', 'Analysis', '2x2 prioritization: high impact + easy first', '["Draw a 2x2 grid with Impact (low to high) on one axis and Ease of implementation (low to high) on the other","List all candidate solutions from your brainstorming or logic tree","Place each solution on the grid based on estimated impact and implementation difficulty","Prioritize high-impact/high-ease solutions first; consider collaboration to shift hard items toward easy","Discard or defer low-impact/low-ease solutions"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'ps101'), 'Pros-and-Cons Grid', 'Analysis', 'Side-by-side benefits and drawbacks of multiple options', '["List all options you are deciding between as column headers","Define the evaluation criteria as row headers (e.g., cost, quality, location)","Fill in the pros and cons for every option against every criterion","Actively look for negatives in attractive options and positives in unattractive ones to counter bias","Compare side-by-side and select the option with the strongest overall balance"]'::jsonb, NULL);
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'eg'), 'Confidence Meter', 'Validation', 'Scale from 0.01 (self-conviction) to 10+ (launch data) measuring evidence strength', '["Rate your idea''s supporting evidence on the scale: self-conviction (0.01), thematic support (0.05), others'' opinion (0.1), estimates/plans (0.3), anecdotal evidence (0.5), market data (1.0), user evidence (2-3), test results (5), launch data (10)","Assign the confidence score that matches the strongest evidence you currently hold","Use the score as the Confidence factor in your ICE calculation","Identify which validation step would move you to the next confidence tier","Re-score after each validation step and adjust investment accordingly"]'::jsonb, '/figures/evidence_guided/evidence_guided_p25.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'eg'), 'North Star Metric', 'Measurement', 'Core value delivered to market, aggregate number that grows over time', '["Identify the core value your product delivers to users (not revenue, but the experience itself)","Express that value as a single aggregate number that grows over time (e.g., messages sent per month)","Verify it is simple enough for the entire organization to understand and remember","Pair it with a Top Business Metric (e.g., revenue) to create the value exchange loop","Revisit and refine if the metric no longer reflects where the product delivers its core value"]'::jsonb, '/figures/evidence_guided/evidence_guided_p39.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'eg'), 'Metrics Trees', 'Measurement', 'Hierarchy decomposing top-level metrics into actionable submetrics teams can own', '["Place the North Star Metric and Top Business Metric at the root level","Decompose each into contributing sub-metrics (input metrics that teams can influence)","Continue branching until each leaf metric can be owned by a single team","Check for overlap between the value-delivery tree and the value-capture tree; high overlap signals good alignment","Add supplementary goals (code health, privacy, employee wellbeing) that the tree does not capture"]'::jsonb, '/figures/evidence_guided/evidence_guided_p42.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'eg'), 'Idea Bank', 'Discovery', 'Repository with states: Triage, Parked, Candidates (<40), Working-Set (3-5)', '["Create a shared repository (spreadsheet, tool) open for anyone to submit ideas","Triage incoming ideas: tag with relevant goal, estimate initial ICE scores","Sort ideas into states: Parked (majority), Candidates (shortlist under 40), Working-Set (3-5 per goal)","Review the bank regularly; promote promising ideas to Candidates and archive stale ones","Assign a single owner (usually the PM) to keep the bank organized and visible"]'::jsonb, '/figures/evidence_guided/evidence_guided_p57.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'eg'), 'ICE Score', 'Discovery', 'Impact x Confidence x Ease, each 0-10, to prioritize ideas over opinions', '["Estimate Impact: how much will this idea move the target metric? Score 0-10","Estimate Ease: what is the inverse of effort in person-weeks? Score 0-10 (10 = less than one week)","Assess Confidence using the Confidence Meter scale to score 0-10","Calculate ICE = Impact x Confidence x Ease to get a comparable ranking number","Treat scores as dynamic hints; re-score as new evidence arrives from validation steps"]'::jsonb, '/figures/evidence_guided/evidence_guided_p89.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'eg'), 'AFTER Model', 'Validation', 'Five validation stages: Assessment, Fact-Finding, Tests, Experiments, Release', '["Assessment: run quick internal evaluations (ICE analysis, assumption mapping, stakeholder review)","Fact-Finding: gather external data through user interviews, surveys, data mining, and competitive analysis","Tests: measure real user reactions with low-cost fakes (fake door tests, Wizard of Oz, concierge tests, usability tests)","Experiments: run controlled tests to reduce bias (A/B tests, multivariate tests) with predetermined success criteria","Release: manage the final rollout via percent launches, holdback experiments, and dogfooding before full deployment"]'::jsonb, '/figures/evidence_guided/evidence_guided_p92.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'eg'), 'GIST Board', 'Process', 'Visual board with three columns: Goals, Ideas, Steps', '["Create three columns on a physical or digital board: Goals (OKRs), Ideas (actively pursued), Steps (next 2-4 actions per idea)","Populate Goals with the team''s current OKR outcomes","Link each active idea to a goal and display its current ICE score and confidence level","List the upcoming validation steps for each idea and update them as evidence is collected","Review the board every 1-2 weeks in a 30-minute trio meeting (PM, Designer, Engineering Lead)"]'::jsonb, '/figures/evidence_guided/evidence_guided_p106.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'eg'), 'Step Document', 'Process', 'Template: what to test, who, how, what to measure, success criteria', '["State what to test: the core assumption or hypothesis being validated","Define who to test with: the target user segment and sample size","Describe how to test: the method (prototype, fake door, Wizard of Oz, A/B test, etc.)","Specify what to measure: the data points to collect and success criteria (set before the test runs)","Summarize results and next action: update the confidence score and decide to continue, pivot, or park the idea"]'::jsonb, '/figures/evidence_guided/evidence_guided_p112.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'eg'), 'Outcome Roadmap', 'Strategy', 'Timeline of Key Results; outputs appear only after reaching high confidence', '["Define the timeline horizon (e.g., quarterly or yearly) and place Key Results as milestones","Show target metric values at each milestone rather than feature names","Add validated, high-confidence ideas as committed deliverables only after they pass through Steps","Keep low-confidence ideas off the roadmap; reference them in the Idea Bank instead","Share with stakeholders so Sales and Marketing communicate customer needs being addressed rather than promising specific unvalidated features"]'::jsonb, '/figures/evidence_guided/evidence_guided_p137.png');
