INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'ppd'), 'Vision Iteration Template', 'Strategy', '"Today, when [segment] want to [activity], they have to [current solution]..."', '[]'::jsonb, '/figures/ppd/ppd_w06v_p16.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'ppd'), 'RWW Screening', 'Strategy', 'Go/no-go: Is it Real? Can we Win? Is it Worth it?', '[]'::jsonb, '/figures/ppd/ppd_w05_p20.png');
