INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'ppd'), 'Diamond-Square Framework', 'Strategy', 'Four pillars: Customer Value Prop, Tech & Ops, Go-to-Market, Profit Formula', '[]'::jsonb, '/figures/ppd/ppd_w05_p5.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'ppd'), 'Mission Model Canvas', 'Strategy', 'BMC variant for mission-driven/non-profit organizations', '[]'::jsonb, '/figures/ppd/ppd_w05_p9.png');
