INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'ppd'), 'Investment Readiness Level (IRL)', 'Strategy', '9-level scale from first BMC (IRL 1) to validated metrics (IRL 9)', '[]'::jsonb, '/figures/ppd/ppd_w05_p24.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'ppd'), 'Empathy Map', 'Discovery', 'Four quadrants: Says, Thinks, Does, Feels for a specific user', '[]'::jsonb, '/figures/ppd/ppd_w03_p46.png');
