INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'ppd'), 'Market Segmentation (4 Types)', 'Discovery', 'Demographic (Who), Psychographic (Why), Geographic (Where), Behavioral (How)', '[]'::jsonb, '/figures/ppd/ppd_w02_p12.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'ppd'), 'Customer Journey Map (CJM)', 'Discovery', 'Visualize touchpoints, friction, emotions, and moments of truth across the user journey', '[]'::jsonb, '/figures/ppd/ppd_w03_p50.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'ppd'), 'Ad-lib Value Proposition Template', 'Discovery', '"Our [product] helps [segment] who want to [job] by [benefit] and [benefit] unlike [competitor]"', '[]'::jsonb, '/figures/ppd/ppd_w04_p25.png');
