INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'ppd'), 'PESTEL Analysis', 'Analysis', 'Macro-external: Political, Economic, Social, Technological, Environmental, Legal', '[]'::jsonb, '/figures/ppd/ppd_w05_p16.png');
INSERT INTO pm_artifact (book_id, name, category, description, how_to, figure) VALUES ((SELECT id FROM pm_book WHERE slug = 'ppd'), 'Porter''s Five Forces', 'Analysis', 'Competitive intensity: rivalry, new entrants, substitutes, supplier power, buyer power', '[]'::jsonb, '/figures/ppd/ppd_w05_p14.png');
